{
  "$schema": "../../node_modules/nx/schemas/project-schema.json",
  "projectType": "library",
  "name": "@compose/js",
  "version": "0.1.0",
  "type": "module",
  "scripts": {
    "build": "tsc --noEmit",
    "test": "cross-env COMPOSE_JS_RUN_EMBEDDED_TESTS=1 vitest run",
    "test:unit": "cross-env COMPOSE_JS_RUN_EMBEDDED_TESTS=1 vitest run",
    "test:coverage": "vitest run --coverage"
  },
  "dependencies": {
    "rxjs": "^7.8.2",
    "zod": "^4.3.5"
  },
  "devDependencies": {
    "cross-env": "^10.1.0",
    "fast-check": "^3.23.2",
    "@compose/assets": "^1.0.0",
    "@types/node": "^25.0.8",
    "@vitest/coverage-v8": "^4.0.17",
    "typescript": "^5.9.3",
    "vitest": "^4.0.17"
  },
  "author": {
    "name": "Ueli Saluz",
    "email": "ueli@semio-tech.com",
    "url": "https://github.com/usalu"
  },
  "license": "LGPL-3.0-or-later",
  "repository": {
    "type": "git",
    "url": "https://github.com/usalu/semio.git",
    "directory": "compose/js"
  },
  "bundleKind": "library",
  "exports": {
    ".": "./index.ts"
  }
}

{
  "$schema": "./node_modules/nx/schemas/nx-schema.json",
  "defaultBase": "⛳wip",
  "workspaceLayout": {
    "appsDir": "compose",
    "libsDir": "compose"
  },
  "namedInputs": {
    "default": [
      "{projectRoot}/**/*",
      "sharedGlobals"
    ],
    "sharedGlobals": [
      "{workspaceRoot}/package.json",
      "{workspaceRoot}/package-lock.json",
      "{workspaceRoot}/nx.json",
      "{workspaceRoot}/tsconfig.json"
    ],
    "production": [
      "default",
      "!{projectRoot}/**/?(*.)+(spec|test|e2e|integration|stories|story|mdx).[cmjtshx]?([sx])?(.snap)?",
      "!{projectRoot}/.storybook/**"
    ]
  },
  "targetDefaults": {
    "lint": {
      "dependsOn": [
        "^lint"
      ],
      "inputs": [
        "default",
        "^default"
      ],
      "cache": true
    },
    "build": {
      "dependsOn": [
        "^build"
      ],
      "inputs": [
        "production",
        "^production"
      ],
      "cache": true
    },
    "dev": {
      "cache": false
    },
    "test": {
      "dependsOn": [
        "^test"
      ],
      "inputs": [
        "default",
        "^default"
      ],
      "cache": true
    },
    "publish:test": {
      "dependsOn": [
        "^publish:test"
      ],
      "inputs": [
        "default",
        "^default"
      ],
      "cache": true
    },
    "publish": {
      "dependsOn": [
        "^publish"
      ],
      "inputs": [
        "default",
        "^default"
      ],
      "cache": true
    },
    "update": {
      "dependsOn": [
        "^update"
      ],
      "inputs": [
        "default",
        "^default"
      ],
      "cache": true
    }
  },
  "plugins": [
    {
      "plugin": "@nxlv/python",
      "options": {}
    }
  ]
}
